INSERT INTO questions (idx, dataset, example_id, prompt_id, source, subject, question_number, prompt, question, choice_a, choice_b, choice_c, choice_d, answer, gold_passage, gold_idx, generated, subtopic)
VALUES
('mbe_160', 'mbe', '160', '99', 'MBE-1978-83-part1', '', '9', 'The State of Aurora requires licenses of persons "who are engaged in the trade of barbering." It will grant such licenses only to those who are graduates of barber schools located in Aurora, who have resided in the state for two years, and who are citizens of the United States.', 'The requirement that candidates for licenses must be citizens is', 'constitutional as an effort to ensure that barbers speak English adequately', 'constitutional as an exercise of the state''s police power', 'unconstitutional as a bill of attainder', 'unconstitutional as a denial of equal protection', 'D', 'The Equal Protection Clause of the Fourteenth Amendment requires that “all persons similarly situated shall be treated alike” under the law. Plyler v. Doe, 457 U.S. 202, 102 S.Ct. 2382, 72 L.Ed.2d 786 (1982); Wood v. State, 18 S.W.3d 642, 651 (Tex.Crim.App.2000). Broadly speaking, this means that “States must treat like cases alike but may treat unlike cases accordingly.” Vacco v. Quill, 521 U.S. 793, 799, 117 S.Ct. 2293, 138 L.Ed.2d 834 (1997).', 'mbe_125', 0, '9'),
('mbe_161', 'mbe', '161', '99', 'MBE-1978-83-part1', '', '10', 'The State of Aurora requires licenses of persons "who are engaged in the trade of barbering." It will grant such licenses only to those who are graduates of barber schools located in Aurora, who have resided in the state for two years, and who are citizens of the United States.', 'Assume that a resident of the state of Aurora was denied a license because she had been graduated from an out-of-state barber school. Her suit in federal court to enjoin denial of the license on this ground would be', 'dismissed, because there is no diversity of citizenship', 'dismissed because of the abstention doctrine', 'decided on the merits, because federal jurisdiction extends to controversies between two states', 'decided on the merits, because a federal question is involved', 'D', '“[F]ederal jurisdiction demands not only a contested federal issue, *1010 but a substantial one, indicating a serious federal interest in claiming the advantages thought to be inherent in a federal forum.” Singh, 538 F.3d at 338.', 'mbe_126', 0, '10'),
('mbe_162', 'mbe', '162', '99', 'MBE-1978-83-part1', '', '11', 'The State of Aurora requires licenses of persons "who are engaged in the trade of barbering." It will grant such licenses only to those who are graduates of barber schools located in Aurora, who have resided in the state for two years, and who are citizens of the United States.', 'Which of the following is the strongest ground on which to challenge the requirement that candidates for barber licenses must have been residents of the state for at least two years?', 'The privileges and immunities clause of the Fourteenth Amendment', 'The due process clause of the Fourteenth Amendment', 'The equal protection clause of the Fourteenth Amendment', 'The obligation of contracts clause', 'C', 'The Equal Protection Clause of the Fourteenth Amendment to the United States Constitution, Section 1, commands that no state shall “deny to any person within its jurisdiction the equal protection of the laws.”  The Equal Protection Clause does not prevent all classification, however. It simply forbids laws that treat persons differently when they are otherwise alike in all relevant respects. Nordlinger v. Hahn (1992), 505 U.S. 1, 10, 112 S.Ct. 2326, 120 L.Ed.2d 1.', 'mbe_127', 0, '11'),
('mbe_163', 'mbe', '163', '100', 'MBE-1978-83-part1', '', '12', '', 'John was fired from his job. Too proud to apply for unemployment benefits, he used his savings to feed his family. When one of his children became ill, he did not seek medical attention for the child at a state clinic because he did not want to accept what he regarded as charity. Eventually, weakened by malnutrition, the child died as a result of the illness. John has committed', 'murder', 'involuntary manslaughter', 'voluntary manslaughter', 'no form of criminal homicide', 'B', 'Voluntary manslaughter is an unlawful killing done without malice, in the heat of passion, or in unreasonable belief in the necessity of self-defense.', 'mbe_128', 0, '12'),
('mbe_164', 'mbe', '164', '101', 'MBE-1978-83-part1', '', '13', 'Professor Merrill, in a lecture in her psychology course at a private university, described an experiment in which a group of college students in a neighboring city rushed out and washed cars stopped at traffic lights during the rush hour. She described how people reacted differently-with shock, joy, and surprise. At the conclusion of her report, she said, "You understand, of course, that you are not to undertake this or any other experiment unless you first clear with me." Four of Merrill''s students decided to try the same experiment but did not clear with Merrill. One subject of their experiment, Carr, said, "I was shocked. There were two people on each side of the car. At first I thought negatively. I thought they were going to attack me and thought of driving away. Then I quieted down and decided there were too many dirty cars in the city anyway." Charitable immunity has been abolished in the jurisdiction.', 'If Carr asserts a claim against the students who washed his car, his best theory is', 'assault', 'negligence', 'invasion of privacy', 'false imprisonment', 'A', 'To establish assault, the following elements must be proved: (1) the defendant acted either with the intent of making a contact with the person of the plaintiff or with the intent of putting the plaintiff in apprehension of such a contact; (2) the plaintiff was placed in apprehension of an imminent contact with his or her person by the conduct of the defendant; and (3) such contact was or appeared to be harmful or offensive.', 'mbe_129', 0, '13'),
('mbe_165', 'mbe', '165', '101', 'MBE-1978-83-part1', '', '14', 'Professor Merrill, in a lecture in her psychology course at a private university, described an experiment in which a group of college students in a neighboring city rushed out and washed cars stopped at traffic lights during the rush hour. She described how people reacted differently-with shock, joy, and surprise. At the conclusion of her report, she said, "You understand, of course, that you are not to undertake this or any other experiment unless you first clear with me." Four of Merrill''s students decided to try the same experiment but did not clear with Merrill. One subject of their experiment, Carr, said, "I was shocked. There were two people on each side of the car. At first I thought negatively. I thought they were going to attack me and thought of driving away. Then I quieted down and decided there were too many dirty cars in the city anyway." Charitable immunity has been abolished in the jurisdiction.', 'If Carr has a valid claim against the students, will he also prevail against the university?', 'Yes, if the students would not have performed the experiment but for Merrill''s lecture.', 'Yes, if Carr''s claim against the students is based on negligence.', 'No, because the students were not Merrill''s employees.', 'No, because Merrill did not authorize the car wash as a class project.', 'D', '“Vicarious liability ‘means that the act or omission of one person ... is imputed by operation of law to another,’ ” without regard to fault. (Srithong v. Total Investment Co. (1994) 23 Cal.App.4th 721, 726, 28 Cal.Rptr.2d 672, italics added.) For example, vicarious liability for torts is imposed by operation of law upon employers for acts of their employees within the course and scope of employment, or upon principals for the acts of their agents.', 'mbe_130', 0, '14'),
('mbe_166', 'mbe', '166', '102', 'MBE-1978-83-part1', '', '15', '', 'Oxnard owned Goldacre, a tract of land, in fee simple. At a time when Goldacre was in the adverse possession of Amos, Eric obtained the oral permission of Oxnard to use as a road or driveway a portion of Goldacre to reach adjoining land, Twin Pines, which Eric owned in fee simple. Thereafter, during all times relevant to this problem, Eric used this road across Goldacre regularly for ingress and egress between Twin Pines and a public highway. Amos quit possession of Goldacre before acquiring title by adverse possession. Without any further communication between Oxnard and Eric, Eric continued to use the road for a total period, from the time he first began to use it, sufficient to acquire an easement by prescription. Oxnard then blocked the road and refused to permit its continued use. Eric brought suit to determine his right to continue use of the road. Eric should', 'win, because his user was adverse to Amos and once adverse it continued adverse until some affirmative showing of a change', 'win, because Eric made no attempt to renew permission after Amos quit possession of Goldacre', 'lose, because his user was with permission', 'lose, because there is no evidence that he continued adverse user for the required period after Amos quit possession', 'C', '“To constitute adverse possession, the possession must be continuous, hostile, open, actual, notorious and exclusive for ... [the required] statutory period.” Davis v. Monteith, 289 S.C. 176, 180, 345 S.E.2d 724, 726 (1986).', 'mbe_131', 0, '15'),
('mbe_167', 'mbe', '167', '103', 'MBE-1978-83-part1', '', '16', 'A brother and sister, Bruce and Sharon, acquired as joint tenants a twenty-acre parcel of land called Greenacre. They contributed equally to the purchase price. Several years later, Bruce proposed that they build an apartment development on Greenacre. Sharon rejected the proposal but orally agreed with Bruce that Bruce could go ahead on his own on the northerly half of Greenacre and Sharon could do what she wished with the southerly half of Greenacre. Bruce proceeded to build an apartment development on, and generally developed and improved, the northerly ten acres of Greenacre. Sharon orally permitted the southerly ten acres of Greenacre to be used by the Audubon Society as a nature preserve. Bruce died, leaving his entire estate to his son, Stanley. The will named Sharon as executrix of his will, but she refused so to serve.', 'In an appropriate action to determine the respective interests of Sharon and Stanley in Greenacre, if Stanley is adjudged to be the owner of the northerly ten acres of Greenacre, the most likely reason for the judgment will be that', 'the close blood relationship between Sharon and Bruce removes the necessity to comply with the Statute of Frauds', 'Sharon''s conduct during Bruce''s lifetime estops her from asserting title to the northerly half of Greenacre', 'the joint tenancy was terminated by the oral agreement of Sharon and Bruce at the time it was made', 'Sharon had a fiduciary obligation to her nephew Stanley by reason of her being named executrix of Bruce''s will', 'B', 'Estoppel is a legal principle that prevents someone from arguing something or asserting a right that contradicts what they previously said or agreed to by law. It is meant to prevent people from being unjustly wronged by the inconsistencies of another person''s words or actions.', 'mbe_132', 0, '16'),
('mbe_168', 'mbe', '168', '103', 'MBE-1978-83-part1', '', '17', 'A brother and sister, Bruce and Sharon, acquired as joint tenants a twenty-acre parcel of land called Greenacre. They contributed equally to the purchase price. Several years later, Bruce proposed that they build an apartment development on Greenacre. Sharon rejected the proposal but orally agreed with Bruce that Bruce could go ahead on his own on the northerly half of Greenacre and Sharon could do what she wished with the southerly half of Greenacre. Bruce proceeded to build an apartment development on, and generally developed and improved, the northerly ten acres of Greenacre. Sharon orally permitted the southerly ten acres of Greenacre to be used by the Audubon Society as a nature preserve. Bruce died, leaving his entire estate to his son, Stanley. The will named Sharon as executrix of his will, but she refused so to serve.', 'In an appropriate action to determine the respective interests of Sharon and Stanley in Greenacre, if Sharon is adjudged to be the owner of all of Greenacre, the most likely reason for the judgment will be that', 'the Statute of Frauds prevents the proof of Sharon''s oral agreement', 'Bruce could not unilaterally sever the joint tenancy', 'Sharon''s nomination as executrix of Bruce''s estate does not prevent her from asserting her claim against Stanley', 'the record title of the joint tenancy in Greenacre can be changed only by a duly recorded instrument', 'A', 'An oral modification of a contract subject to the statute of frauds is never permitted when it would materially alter the parties'' written agreement.53 “Were it possible to make an oral modification of a contract which by the statute of frauds is required to be in writing and enforce such oral modification, the door would be open for the perpetration of such frauds as the statute seeks to prevent.”54', 'mbe_133', 0, '17'),
('mbe_169', 'mbe', '169', '104', 'MBE-1978-83-part1', '', '18', '', 'Mary Webb, a physician, called as a witness by the defendant in the case of Parr v. Doan, was asked to testify to statements mTd by Michael Zadok, her patient, for the purpose of obtaining treatment from Dr. Webb. Which of the following is the best basis for excluding evidence of Zadok''s statements in a jurisdiction with a doctor-patient privilege?', 'An objection by Dr. Webb asserting her privilege against disclosure of confidential communications made by a patient', 'An objection by Parr''s attorney on the grounds of the doctor -patient privilege', 'A finding by the trial judge that Zadok had left the office without actually receiving trearment', 'The assertion of a privilege by Zadok''s attorney, present at the trial as a spectator at Zadok ''s request, and allowed by the trial judge to speak', 'D', 'the privilege applies to all circumstances in which a physician or psychologist is called on to give testimony or produce records concerning information that was acquired from a patient, regardless of whether the information will be used against the patient.', 'mbe_134', 0, '18'),
('mbe_170', 'mbe', '170', '105', 'MBE-1978-83-part1', '', '19', '', 'A leading question is LEAST likely to be permitted over objection when', 'asked on cross -examination of an expert witness', 'asked on direct examination of a young child', 'asked on direct examination of a disinterested eyewitness', 'related to preliminary matters such as the name or occupation of the witness', 'C', 'A party is permitted to ask leading questions on direct examination when a party calls a hostile witness, an adverse party, or a witness identified with an adverse party, and there is no limit on the number of leading questions the party may ask.', 'mbe_135', 0, '19'),
('mbe_171', 'mbe', '171', '106', 'MBE-1978-83-part1', '', '20', 'Passer was driving his pickup truck along a lonely
road on a very cold night. Passer saw Tom, who was
a stranger, lying in a field by the side of the road and
apparently injured. Passer stopped his truck, alighted,
and, upon examining Tom, discovered that Tom was
intoxicated and in danger of suffering from exposure
to the cold. However, Passer returned to his truck
and drove away without making any effort to help Tom.
Tom remained lying at the same place and was
later injured when struck by a car driven by
Traveler. Traveler, who was drowsy and inattentive,
had veered off the road into the field and hit Tom.
Traveler did not see Tom prior to hitting him.', 'If Tom asserts a claim against Passer for damages for his injuries, will Tom prevail?', 'Yes, because by stopping and examining Tom, Passer assumed a duty to aid him.', 'Yes, if a reasonably prudent person under the circumstances would have aided Tom.', 'No, if Passer did not, in any way, make Tom''s situation worse.', 'No, because Tom himself created the risk of harm by becoming intoxicated.', 'C', 'Our analysis of these issues begins by noting that, at common law, there is no general duty to rescue. See W. Page Keeton et al., Prosser & Keeton on Torts § 56 at 375 (5th ed. 1984) (“[T]he law has persistently refused to impose on a stranger the moral obligation of common humanity to go to the aid of another human being who is in danger, even if the other is in danger of losing his life.”). Further, we have recognized “ ‘[i]t is ancient learning that one who assumes to act, even though gratuitously, may thereby become subject to the duty of acting carefully, if he acts at all.’ ” Didato v. Strehler, 262 Va. 617, 628, 554 S.E.2d 42 (2001) (quoting Nolde Bros. v. Wray, 221 Va. 25, 28, 266 S.E.2d 882 (1980)).', 'mbe_136', 0, '20'),
('mbe_172', 'mbe', '172', '106', 'MBE-1978-83-part1', '', '21', 'Passer was driving his pickup truck along a lonely
road on a very cold night. Passer saw Tom, who was
a stranger, lying in a field by the side of the road and
apparently injured. Passer stopped his truck, alighted,
and, upon examining Tom, discovered that Tom was
intoxicated and in danger of suffering from exposure
to the cold. However, Passer returned to his truck
and drove away without making any effort to help Tom.
Tom remained lying at the same place and was
later injured when struck by a car driven by
Traveler. Traveler, who was drowsy and inattentive,
had veered off the road into the field and hit Tom.
Traveler did not see Tom prior to hitting him.', 'If Tom asserts a claim against Traveler, will Tom prevail?', 'Yes, because Traveler was negligent in going off the road.', 'Yes, because Tom was in a helpless condition.', 'No, because Traveler did not see Tom before Tom was struck.', 'No, because Tom''s intoxication was the cause in fact of his harm.', 'A', 'In order to sustain a claim for negligence, a plaintiff must be able to establish “(1) a legal duty; (2) a breach of this duty; (3) an injury; and (4) a causal connection between the breach and the injury.” Persinger v. Step By Step Infant Dev. Ctr., 253 Ga. App. 768, 769, 560 S.E.2d 333 (2002) (quoting Vaughan v. Glymph, 241 Ga. App. 346, 348, 526 S.E.2d 357 (1999) ). In this Court''s review of Plaintiff''s original compliant, the Court found that Plaintiff failed to establish that Defendant owed Plaintiff any legal duty to protect her from harm. (Doc. 36 at 10.) Instead, the Court found that Plaintiff merely relied on a series of conclusory allegations that merely stated that Defendant owed her a duty. (Id.)', 'mbe_137', 0, '21'),
('mbe_173', 'mbe', '173', '107', 'MBE-1978-83-part1', '', '22', '', 'Roofer entered into a written contract with Orissa to repair the roof of Orissa''s home, the repairs to be done "in a workmanlike manner." Roofer completed the repairs and took all of his equipment away, with the exception of a 20-foot extension ladder, which was left against the side of the house. He intended to come back and get the ladder the next morning. At that time, Orissa and her family were away on a trip. During the night, a thief, using the ladder to gain access to an upstairs window, entered the house and stole some valuable jewels. Orissa has asserted a claim against Roofer for damages for the loss of the jewels. In her claim against Roofer, Orissa will', 'prevail, because by leaving the ladder Roofer became a trespasser on Orissa''s property', 'prevail, because by leaving the ladder Roofer created the risk that a person might unlawfully enter the house', 'not prevail, because the act of the thief was a superseding cause', 'not prevail, because Orissa''s claim is limited to damages for breach of contract', 'B', 'Proximate cause is the cause that in a natural and continuous sequence, unbroken by any superseding cause, both produced the injury and was necessary for the injury. The injury must be the natural and probable consequence of the wrongful act. Individuals are not responsible for all possible consequences arising from their negligence—just those that are probable according to ordinary and usual experience. An event may have more than one but-for cause. Any perceived distinction between the phrases “causing an event” and “contributing to an event” is a distinction without a difference. In other words, an act of negligence that contributes to an event must, of necessity, have at least a part in causing the event.', 'mbe_138', 0, '22'),
('mbe_174', 'mbe', '174', '108', 'MBE-1978-83-part1', '', '23', '', 'Homer and Purcell entered into a valid, enforceable written contract by which Homer agreed to sell and Purcell agreed to purchase Blackacre, which was Homer ''s residence. One of the contract provisions was that after the closing Homer had the right to remain in residence at Blackacre for up to 30 days before delivering possession to Purcell. The closing took place as scheduled. Title passed to Purcell and Homer remained in possession. Within a few days after the closing, the new house next door which was being constructed for Homer was burned to the ground, and at the end of the 30-day period Homer refused to move out of Blackacre; instead, Homer tendered to Purcell a monthly rental payment in excess of the fair rental value of Blackacre. Purcell rejected the proposal and that day brought an appropriate action to gain immediate possession of Blackacre. The contract was silent as to the consequences of Homer ''s failure to give up possession within the 30-day period, and the jurisdiction in which Blackacre is located has no statute dealing directly with this situation, although the landlord-tenant law of the jurisdiction requires a landlord to give a tenant 30 days notice before a tenant may be evicted. Purcell did not give Homer any such 30-day statutory notice. Purcell''s best legal argument in support of his action to gain immediate possession is that Homer is a', 'trespasser ab initio', 'licensee', 'tenant at sufferance', 'tenant from month to month', 'B', 'Conversely, a person who enters the premises of another by permission or acquiescence, for his own pleasure or benefit, and not by invitation, is a licensee. A licensee takes his license subject to its attendant perils and risks. The licensor is not liable for ordinary negligence and owes the licensee no duty except to refrain from wantonly or willfully causing injury.” Light v. Ohio Univ. (1986), 28 Ohio St.3d 66, 68, 28 OBR 165, 502 N.E.2d 611.', 'mbe_139', 0, '23'),
('mbe_175', 'mbe', '175', '109', 'MBE-1978-83-part1', '', '24', 'Albert engaged Bertha, an inexperienced actress, to do a small role in a new Broadway-play for a period of six months at a salary of $200 a week. Bertha turned down another role in order to accept this engagement. On the third day of the run, Bertha was hospitalized with influenza and Helen was hired to do the part. A week later, Bertha recovered, but Albert refused to accept her services for the remainder of the contract period. Bertha then brought an action against Albert for breach of contract.', 'Which of the following is Bertha''s best legal theory?', 'Her acting contract with Albert was legally severable into weekly units.', 'Her performance of the literal terms of the contract was physically impossible.', 'Her reliance on the engagement with Albert by declining another acting role created an estoppel against Albert.', 'Her failure to perform for one week was not a material failure so as to discharge Albert''s duty to perform.', 'D', 'A material breach of contract “is a non-performance of a duty that is so material and important as to justify the injured party in regarding the whole transaction as at an end.” *6 Jenkins, Inc. v. Walsh Bros., Inc., 2001 ME 98, ¶ 13, 776 A.2d 1229, 1234 (quotation marks omitted); see also Forrest Assocs. v. Passamaquoddy Tribe, 2000 ME 195, ¶ 9, 760 A.2d 1041, 1044 (stating that “whether a breach has occurred ... [is a] question [ ] of fact”).', 'mbe_140', 0, '24'),
('mbe_176', 'mbe', '176', '109', 'MBE-1978-83-part1', '', '25', 'Albert engaged Bertha, an inexperienced actress, to do a small role in a new Broadway-play for a period of six months at a salary of $200 a week. Bertha turned down another role in order to accept this engagement. On the third day of the run, Bertha was hospitalized with influenza and Helen was hired to do the part. A week later, Bertha recovered, but Albert refused to accept her services for the remainder of the contract period. Bertha then brought an action against Albert for breach of contract.', 'Which of the following, if true, would adversely affect Bertha''s rights in her action against Albert?', 'Albert could not find any substitute except Helen, who demanded a contract for a minimum of six months if she was to perform at all.', 'Helen, by general acclaim, was much better in the role than Bertha had been.', 'Albert had offered Bertha a position as Helen''s understudy at a salary of $100 a week, which Bertha declined.', 'Albert had offered Bertha a secretarial position at a salary of $300 a week, which Bertha declined.', 'A', 'Like merger, ratification is an affirmative defense. Land Title Co. of Dall., Inc. v. F.M. Stigler, Inc., 609 S.W.2d 754, 756 (Tex.1980). It is “the adoption or confirmation by a person, with knowledge of all material facts, of a prior act which did not then legally bind that person and which that person had the right to repudiate.” Chrisman v. Electrastart of Hous., Inc., No. 14–02–00516–CV, 2003 WL 22996909, at *5 (Tex.App.-Houston [14th Dist.] Dec. 23, 2003, no pet.) (mem. op.). Whether a person has ratified an act is “essentially a question of fact, to be determined from all the circumstances [in] evidence.” Id. (quoting Colvin v. Blanchard, 103 S.W. 1118, 1119 (Tex.Civ.App.-Fort Worth 1907), aff''d, 101 Tex. 231, 106 S.W. 323 (1908)).', 'mbe_141', 0, '25'),
('mbe_177', 'mbe', '177', '110', 'MBE-1978-83-part1', '', '26', '', 'Park sued Dent for breach of an oral contract which Dent denied making. Weston testified that he heard Dent make the contract on July 7. Dent discredited Weston, and Park offers evidence of Weston''s good reputation for truthfulness. The rehabilitation is most likely to be permitted if the discrediting evidence by Dent was testimony that', 'Weston had been promoting highly speculative stocks', 'Weston had been Park''s college roommate', 'Weston had attended a school for mentally retarded children', 'Weston had been out of town the whole week of July 4-10', 'D', 'Parol, or extrinsic, evidence is only admissible if the terms of the contract are ambiguous, and can only be used to interpret, not contradict, the express language of the contract. Lincoln Elec. Co., 210 F.3d at 684. If the language of a contract “is clear and unambiguous ... there is no issue of fact to be determined.” Id. Ambiguity exists “where contract language is susceptible to two or more reasonable interpretations.” Glidden Co. v. Kinsella, 386 Fed.Appx. 535, 542 (6th Cir.2010) (quoting Potti v. Duramed Pharm. Inc., 938 F.2d 641, 647 (6th Cir.1991)). However, a term is not ambiguous merely because two parties offer substantially different interpretations. Id.; accord 216 Jamaica Ave., LLC v. S & R Playhouse Realty Co., 540 F.3d 433, 440 (6th Cir.2008). Permissible “extrinsic evidence may include (1) the circumstances surrounding *591 the parties at the time the contract was made, (2) the objectives the parties intended to accomplish by entering into the contract, and (3) any acts by the parties that demonstrate the construction they gave their agreement.” United States Fid. & Guar. Co. v. St. Elizabeth Med. Ctr., 129 Ohio App.3d 45, 716 N.E.2d 1201, 1208 (1998).', 'mbe_142', 0, '26'),
('mbe_178', 'mbe', '178', '111', 'MBE-1978-83-part1', '', '27', 'Lawyers Abel and Baker are the members of the law partnership of Abel and Baker in a small town that has only one other lawyer in it. Abel and Baker do a substantial amount of personal injury work. Client was severely and permanently injured in an automobile collision when struck by an automobile driven by Motorist. Client employed the Abel and Baker firm to represent her in obtaining damages for her injuries. At the time Client employed Abel and Baker, the statute of limitations had six weeks to run on her claim. The complaint was prepared but not filed. Abel and Baker each thought chat the other would file the complaint. The statute of limitations ran on Client''s claim against Motorist. Client has filed suit against Abel and Baker for negligence. That case is on trial with a jury in a court of general jurisdiction.', 'In order to establish a breach of the standard of care owed to her by Abel and Baker, Client', 'must have a legal expert from the same locality testify that defendants'' conduct was a breach', 'must have a legal expert from the same state testify that defendants'' conduct was a breach', 'can rely on the application of the jurors'' common knowledge as to whether there was a breach', 'can rely on the judge, as an expert in the law, to advise the jury whether there was a breach', 'C', 'In a medical malpractice case, the relevant standard of care is that of a reasonably careful physician acting as a specialist in the same field of practice. See Short v. Kinkade, 685 P.2d 210 (Colo.App.1983); see also CJI–Civ. 4th 15:3 (2001). To determine whether the applicable standard of care has been violated, the jury must compare the defendant''s conduct with what a reasonably careful physician would do under the same circumstances. See Greene v. Thomas, 662 P.2d 491 (Colo.App.1982); see also CJI–Civ. 4th 15:3 (2001). Because the applicable standard of care is not within the common knowledge and experience of ordinary people, the standard must be established by expert testimony in a medical malpractice case. United Blood Servs. v. Quintana, 827 P.2d 509, 520 (Colo.1992).', 'mbe_143', 0, '27'),
('mbe_179', 'mbe', '179', '111', 'MBE-1978-83-part1', '', '28', 'Lawyers Abel and Baker are the members of the law partnership of Abel and Baker in a small town that has only one other lawyer in it. Abel and Baker do a substantial amount of personal injury work. Client was severely and permanently injured in an automobile collision when struck by an automobile driven by Motorist. Client employed the Abel and Baker firm to represent her in obtaining damages for her injuries. At the time Client employed Abel and Baker, the statute of limitations had six weeks to run on her claim. The complaint was prepared but not filed. Abel and Baker each thought chat the other would file the complaint. The statute of limitations ran on Client''s claim against Motorist. Client has filed suit against Abel and Baker for negligence. That case is on trial with a jury in a court of general jurisdiction.', 'In addition to proving that Abel and Baker were negligent, Client must establish, as a minimum, that she', 'would have, but for her lawyers'' negligence, recovered from Motorist', 'had a good faith claim against Motorist that was lost by her lawyers'' negligence', 'was severely and permanently injured when struck by Motorist''s automobile', 'did not negligently contribute to the failure to have the complaint filed', 'A', 'Because an attorney''s negligence is imputed to his client, Hatami–Miri is unable to establish “cause” for his procedural default. See Lee v. INS, 685 F.2d 343 (9th Cir.1982) (dismissing a petition for review from the BIA as untimely where petitioners did not receive timely notice of the BIA''s decision because their attorney filed a change of address with the INS rather than the BIA). Nakaranurack v. United States, 68 F.3d 290 (9th Cir.1995), does not dictate otherwise. Rather than creating an exception to the rule that one is bound by the negligence of one''s counsel, Nakaranurack merely declined to “impute negligence on the part of [petitioner''s] attorney” without evidence that the BIA provided timely notice of its decision. Id. at 294.', 'mbe_144', 0, '28'),
('mbe_180', 'mbe', '180', '112', 'MBE-1978-83-part1', '', '29', '', 'A state statute divides murder into degrees. First degree murder is defined as murder with premeditation and deliberation or a homicide in the commission of arson, rape, robbery, burglary or kidnapping. Second degree murder is all other murder at common law. In which of the following situations is Defendant most likely to be guilty of first degree murder?', 'Immediately after being insulted by Robert, Defendant takes a knife and stabs and kills Robert.', 'Angered over having been struck by Sam, Defendant buys rat poison and puts it in Sam''s coffee. Sam drinks the coffee and dies as a result.', 'Intending to injure Fred, Defendant lies in wait and, as Fred comes by, Defendant strikes him with a broom handle. As a result of the blow, Fred dies.', 'Defendant, highly intoxicated, discovers a revolver on a table. He picks it up, points it at Alice, and pulls the trigger. The gun discharges, and Alice is killed.', 'B', 'For a first-degree murder conviction, the prosecution must show (1) the defendant caused the death of the victim, (2) with malice aforethought, and (3) with premeditation. See United States v. Wood, 207 F.3d 1222, 1228 (10th Cir. 2000); Tenth Circuit Criminal Pattern Jury Instruction 2.52 (Feb. 2018 update). The “malice [requirement] is not satisfied simply by killing with an intentional or reckless mental state; instead, malice specifically requires committing the wrongful act without justification, excuse, or mitigation.” Currie, 911 F.3d at 1054 (quotations omitted).', 'mbe_145', 0, '29'),
('mbe_181', 'mbe', '181', '113', 'MBE-1978-83-part1', '', '30', '', 'On a camping trip in a state park, Rose discovered metal signs near a rubbish heap stating, "Natural Wildlife Area-No Hunting." She took two of the signs and used them to decorate her room at home. She is charged with violation of a state statute which provides, "Any person who appropriates to his own use property owned by the state shall be guilty of a crime and shall be punished by a fine of not more than $1,000, or by imprisonment for not more than five years, or by both such fine and imprisonment." At trial, Rose admits taking the signs but says she believedI they had been thrown away. In fact, the signs had not been abandoned. Rose should be found', 'guilty, because this is a public welfare offense', 'guilty, because she should have inquired whether the signs were abandoned', 'not guilty if the jury finds she honestly believed the signs had been abandoned', 'not guilty unless the jury finds that the state had taken adequate steps to inform the public that the signs had not been abandoned', 'C', '“Appellant''s defense that he believed the [automobile] abandoned is essentially a defense of mistake of fact,” and “[i]n general intent crimes, ... a defendant may interpose a mistake of fact defense if the defendant proves ‘to the satisfaction of the fact finder that the mistake was both (1) honest and (2) reasonable.’ ” Simms, 612 A.2d at 218 (quoting Williams, 337 A.2d at 774–75) (further citations omitted). In this appeal, we are not asked to and do not revisit whether the language just quoted connotes a shift to the defendant of the burden of both persuasion and production of evidence. See generally Mullaney v. Wilbur, 421 U.S. 684, 695 n. 20, 701 n. 28, 702 n. 30, 95 S.Ct. 1881, 44 L.Ed.2d 508 (1975).', 'mbe_146', 0, '30'),
('mbe_182', 'mbe', '182', '114', 'MBE-1978-83-part1', '', '31', '', 'Ted frequently visited Janet, his next-door neighbor. Janet was separated from her husband, Howard. Howard resided with his mother but jointly owned the house in which Janet resided. Late one night, Teo and Janet were sitting on the bed in Janet''s bedroom drinking when Howard burst through the door and told Ted, "Get out I" When Ted refused, Howard challenged him to go outside and "fight it out." Ted again refused. Howard then pulled a knife from his pocket and lunged at Ted. Ted grabbed a lamp, struck Howard on the head, and killed him. Ted is charged with murder. On a charge of murder, Ted should be found', 'not guilty, because Ted had as much right as Howard to be in the house', 'not guilty, because Howard attacked Ted with a deadly weapon', 'guilty, because Ted''s presence in Janet''s bedroom prompted Howard''s attack', 'guilty, because Ted''s failure to obey Howard''s order to leave the house made him a trespasser', 'B', '“The amount of force that an individual may use to protect himself must be proportionate to the urgency of the situation.  When a person uses more force than is reasonably necessary under the circumstances, the right of self-defense is extinguished.” Hall, 166 N.E.3d at 414 (quoting Pinkston v. State, 821 N.E.2d 830, 842 (Ind. Ct. App. 2004), trans. denied (2005)).', 'mbe_147', 0, '31'),
('mbe_183', 'mbe', '183', '115', 'MBE-1978-83-part1', '', '32', 'In 1970, Oscar, owner of a 100-acre tract, prepared and duly recorded a subdivision plan called Happy Acres. The plan showed 90 one-acre lots and a ten-acre tract in the center that was designated "Future Public School." Oscar published and distributed a brochure promoting Happy Acres which emphasized the proximity of the lots to the school property and indicated potential tax savings "because the school district will not have to expend tax money to-acquire this property." There is no specific statute concerning the dedication of school sites. Oscar sold 50 of the lots to individual purchasers. Each deed referred to the recorded plan and also contained the following clause: "No mobile home shall be erected on any lot within Happy Acres." Sarah was one of the original purchasers from Oscar. In 1976, Oscar sold the remaining 40 lots and the ten-acre tract to Max by a deed which referred to the plan and contained the restriction relating to mobile homes. Max sold the 40 lots to individual purchasers and the ten-acre tract to Pete. None of the deeds from Max referred to the plan or contained any reference to mobile homes.', 'Assume for this question only that Pete has announced his intention of erecting a fast food restaurant on the ten-acre tract and that Sarah has filed an action to enjoin Pete. If Sarah wins, it will be because', 'Sarah has an equitable servitude concerning the use of the tract', 'Sarah, as a taxpayer, has a legal interest in the use of the tract', 'Sarah is a creditor beneficiary of Oscar''s promise with respect to the tract', 'Pete is not a bona fide purchaser', 'A', 'The Restatement provides: “If injustice can be avoided only by establishment of a servitude, the owner or occupier of land is estopped to deny the existence of a servitude burdening the land when:
“(1) the owner or occupier permitted another to use that land under circumstances in which it was reasonable to foresee that the user would substantially change position believing that the permission would not be revoked, and that user did substantially change position in reasonable reliance on that belief; or
*438 “(2) the owner or occupier represented that the land was burdened by a servitude under circumstances in which it was reasonable to foresee that the person to whom the representation was made would substantially change position on the basis of that representation, and the person did substantially change position in reasonable reliance on that representation.”
Restatement at § 2.10; see also Ebbe v. Senior Estates Golf, 61 Or.App. 398, 657 P.2d 696 (1983) (discussing equitable servitudes). Thus, an equitable servitude by estoppel may be created as the result of (1) either an express or implied representation made under circumstances where (2) it is reasonably foreseeable that the person to whom the representation is made will rely on it, (3) that person does so rely, (4) such reliance is reasonable, and (5) the establishment of a servitude is necessary to avoid injustice.', 'mbe_148', 0, '32'),
('mbe_184', 'mbe', '184', '115', 'MBE-1978-83-part1', '', '33', 'In 1970, Oscar, owner of a 100-acre tract, prepared and duly recorded a subdivision plan called Happy Acres. The plan showed 90 one-acre lots and a ten-acre tract in the center that was designated "Future Public School." Oscar published and distributed a brochure promoting Happy Acres which emphasized the proximity of the lots to the school property and indicated potential tax savings "because the school district will not have to expend tax money to-acquire this property." There is no specific statute concerning the dedication of school sites. Oscar sold 50 of the lots to individual purchasers. Each deed referred to the recorded plan and also contained the following clause: "No mobile home shall be erected on any lot within Happy Acres." Sarah was one of the original purchasers from Oscar. In 1976, Oscar sold the remaining 40 lots and the ten-acre tract to Max by a deed which referred to the plan and contained the restriction relating to mobile homes. Max sold the 40 lots to individual purchasers and the ten-acre tract to Pete. None of the deeds from Max referred to the plan or contained any reference to mobile homes.', 'Assume for this question only that Joe, who purchased his lot from Max, has placed a mobile home on it and that Sarah brings an action against Joe to force him to remove it. The result of this action will be in favor of', 'Sarah. because the restrictive covenant in her deed runs with the land', 'Sarah, because the presence of the mobile home may adversely affect the market value of her land', 'Joe, because his deed did not contain the restrictive covenant', 'Joe, because he is not a direct but a remote grantee of Oscar', 'A', 'In Texas, a covenant runs with the land when four requirements are met: (1) it touches and concerns the land; (2) it relates to a thing in existence or specifically binds the parties and their assigns; (3) it is intended by the original parties to run with the land; and (4) the successor to the burden has notice. In re Energytec, Inc., 739 F.3d 215, 221 (5th Cir. 2013) (citing Inwood N. Homeowners’ Ass''n, Inc. v. Harris, 736 S.W.2d 632, 635 (Tex. 1987)).', 'mbe_149', 0, '33')
